<script setup lang="ts">
import { computed, ref, useId } from 'vue';
import type { DaemonStatus, InputDevice } from '../types';
import { audioControls, DEFAULT_AUDIO_CONTROLS, type AudioControlId, type AudioChange } from './audioControls';
const props = withDefaults(defineProps<{status: DaemonStatus | null; devices?: InputDevice[]; cuesEnabled?: boolean; visible: AudioControlId[]; settings?: boolean}>(), {devices:()=>[],cuesEnabled:true,settings:false});
const emit = defineEmits<{change:[change:AudioChange]; visibility:[ids:AudioControlId[]]; refreshDevices:[]; openSettings:[]}>();
const SETTINGS_MAX_WIDTH = 680;
const prefix = useId();
const openNotice = ref<AudioControlId | null>(null);
const controls = computed(()=>audioControls(props.status,props.devices,props.cuesEnabled).filter(c=>props.settings || props.visible.includes(c.id)));
function toggle(id: AudioControlId, checked: boolean) { emit('visibility', checked ? [...props.visible,id] : props.visible.filter(v=>v!==id)); }
</script>
<template>
  <div class="audio-controls" :class="{settings}" :style="{ '--audio-settings-max-width': SETTINGS_MAX_WIDTH + 'px' }">
    <header v-if="!settings"><span>Audio controls</span><button type="button" aria-label="Open all audio controls" title="Open all audio controls" @click="emit('openSettings')">More ↗</button></header>
    <template v-else><h3>Audio controls</h3><p>All controls are available here. Choose which also appear on your dashboard.</p><div class="visibility-heading">Show on dashboard</div></template>
    <div v-for="c in controls" :key="c.id" class="audio-row" :title="c.notice || (c.disabled ? 'Used in Auto mode' : c.help)">
      <div><div class="control-label"><label :id="`${prefix}-${c.id}-label`" :for="c.buttons ? undefined : `${prefix}-${c.id}`">{{c.label}}</label><span v-if="!settings && c.notice" class="notice-icon" :class="{open:openNotice === c.id}"><button type="button" :aria-label="`${c.label}: ${c.notice}`" :aria-expanded="openNotice === c.id" @click="openNotice = openNotice === c.id ? null : c.id" @blur="openNotice = null" @keydown.esc="openNotice = null"><svg aria-hidden="true" viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M8 2L15 14H1Z"/><path d="M8 6v4m0 1v1"/></svg></button><span :id="`${prefix}-${c.id}-help`" class="notice-tooltip" role="tooltip">{{c.notice}}</span></span></div><p v-if="settings" :id="`${prefix}-${c.id}-help`" class="help" :class="{notice:!!c.notice}">{{c.notice || c.help}}</p></div>
      <div v-if="c.buttons" class="choices" role="group" :aria-labelledby="`${prefix}-${c.id}-label`"><button v-for="o in c.options" :key="o.value" type="button" :disabled="o.disabled || c.disabled" :aria-pressed="c.value === o.value" @click="emit('change',{id:c.id,value:o.value})">{{o.label}}</button></div>
      <select v-else :id="`${prefix}-${c.id}`" :value="c.value" :disabled="c.disabled" :aria-describedby="settings || !!c.notice ? `${prefix}-${c.id}-help` : undefined" @focus="c.id === 'microphone' && emit('refreshDevices')" @change="emit('change',{id:c.id,value:($event.target as HTMLSelectElement).value})"><option v-for="o in c.options" :key="o.value" :value="o.value">{{o.label}}</option></select>
      <label v-if="settings" class="visibility"><input type="checkbox" role="switch" :checked="visible.includes(c.id)" :aria-label="`Show ${c.label} on dashboard`" @change="toggle(c.id,($event.target as HTMLInputElement).checked)"><span class="visibility-track" aria-hidden="true"></span></label>
    </div>
    <p v-if="!settings && !controls.length">Choose controls to show in Settings.</p>
    <button v-if="settings" type="button" @click="emit('visibility',[...DEFAULT_AUDIO_CONTROLS])">Restore default visibility</button>
  </div>
</template>
<style scoped>
.audio-controls{font-size:11px;color:var(--ink)}header{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;gap:8px}header span{font-size:13px;font-weight:600}button,select{font:inherit;color:inherit;background:var(--panel-solid);border:1px solid var(--line);border-radius:3px;padding:4px 5px;min-height:28px;min-width:0}button{cursor:pointer}select{width:100%;text-overflow:ellipsis}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid var(--cyan);outline-offset:2px}.audio-row{display:grid;grid-template-columns:80px minmax(0,1fr);gap:6px;align-items:center;margin:6px 0}.choices{display:flex;gap:4px}.choices button{flex:1;white-space:nowrap}.choices button[aria-pressed=true]{border-color:var(--cyan);background:color-mix(in srgb,var(--cyan) 12%,transparent)}:disabled{opacity:.5;cursor:default}p{color:var(--muted);line-height:1.5}.settings{font-size:13px;width:100%;max-width:var(--audio-settings-max-width);min-width:0;box-sizing:border-box;container-type:inline-size}.settings .audio-row{grid-template-columns:minmax(120px,1fr) 160px 110px;gap:12px;padding:14px 0;border-top:1px solid var(--line);margin:0}.notice{color:#f4c542}.control-label{display:flex;align-items:center;gap:3px}.notice-icon{position:relative;flex:none;color:#f4c542}.notice-icon button{display:flex;align-items:center;cursor:pointer;padding:0;min-height:14px;width:14px;border:0;background:none;color:inherit}.notice-icon button:focus-visible{outline:2px solid #f4c542;outline-offset:3px}.notice-tooltip{display:none;position:absolute;z-index:20;top:calc(100% + 6px);left:-65px;width:230px;padding:9px;background:var(--panel-solid);border:1px solid #f4c542;box-shadow:0 6px 18px #0006;color:#f4c542;white-space:normal;line-height:1.4}.notice-icon:hover .notice-tooltip,.notice-icon:focus-within .notice-tooltip,.notice-icon.open .notice-tooltip{display:block}.help{font-size:12px;margin:5px 0 0}.visibility{justify-self:center;display:block;position:relative;width:34px;height:20px;cursor:pointer}.visibility input{position:absolute;inset:0;width:100%;height:100%;margin:0;opacity:0;z-index:1;cursor:pointer}.visibility-track{display:block;width:34px;height:20px;border:1px solid var(--line);border-radius:12px;background:var(--panel-solid)}.visibility-track::after{content:"";display:block;width:14px;height:14px;border-radius:50%;background:var(--muted);margin:2px;transition:transform .12s}.visibility input:checked + .visibility-track{border-color:var(--cyan);background:color-mix(in srgb,var(--cyan) 20%,var(--panel-solid))}.visibility input:checked + .visibility-track::after{transform:translateX(14px);background:var(--cyan)}.visibility input:focus-visible + .visibility-track{outline:2px solid var(--cyan);outline-offset:3px}.visibility-heading{width:110px;text-align:center;font-size:12px;margin:12px 0 4px auto}h3{font-size:15px;margin:0}.settings .choices{font-size:11px}@container(max-width:460px){.settings .audio-row{grid-template-columns:minmax(0,1fr) 150px}.visibility{grid-column:1/-1}.visibility-heading{display:none}}
@container(max-width:300px){.settings .audio-row{grid-template-columns:minmax(0,1fr)}.visibility{grid-column:auto}}
</style>
